# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.22.0/ankra-cli-darwin-arm64"
      sha256 "01cc7812e62b08aa62451affe2e85e55948c519864d1dca7bea061a2c87410dc"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.22.0/ankra-cli-darwin-amd64"
      sha256 "570bf7f62dac9b9844b645b937d602e6a4dd90f903ba07d6d3210628809a93d0"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.22.0/ankra-cli-linux-arm64"
      sha256 "909bfc89b1c1d6d4d047f3aac4789584855c749c600cd454427a9c88c1864da1"
    end
    on_intel do
